Action.Str:
var data = JSON.parse(local("http_data"));

if (data.fout) {
    setLocal("kleur", "#757575");
    setLocal("spotnaam", "Kite Weer App");
    setLocal("bijgewerkt", "fout bij ophalen");
    setLocal("verdict", data.fout);
    setLocal("score", "-");
    setLocal("windnu", "");
    setLocal("windvlagen", "");
    setLocal("grafiekurl", "");
} else {
    var kleurHex = data.kleur === "groen" ? "#2E7D32" : data.kleur === "oranje" ? "#F57F17" : "#C62828";
    var windnu = (data.windKnopen != null ? data.windKnopen + " kn" : "\u2013") +
        (data.windrichtingKompas ? " \u00b7 " + data.windrichtingKompas : "");
    var windvlagen = data.windvlaagKnopen != null ? "vlagen tot " + data.windvlaagKnopen + " kn" : "";

    setLocal("kleur", kleurHex);
    setLocal("spotnaam", data.spotnaam);
    setLocal("bijgewerkt", "bijgewerkt " + data.bijgewerkt);
    setLocal("verdict", data.verdict);
    setLocal("score", String(data.score));
    setLocal("windnu", windnu);
    setLocal("windvlagen", windvlagen);
    // Leeg als de grafiek niet gebouwd kon worden (zie Code.gs: widgetJson_) - Actie 2 laat het
    // Image-element dan gewoon weg i.p.v. een kapot-plaatje-icoon te tonen.
    setLocal("grafiekurl", data.grafiekUrl || "");
}

var kolomKinderen = [
    {
        type: "Row",
        fillMaxWidth: true,
        verticalAlignment: "Center",
        children: [
            { type: "Text", text: spotnaam, color: "#FFFFFF", textSize: "16", bold: true },
            { type: "Spacer", isWeighted: true },
            { type: "Text", text: bijgewerkt, color: "#E0E0E0", textSize: "12" }
        ]
    },
    {
        type: "Text",
        text: verdict,
        color: "#F5F5F5",
        textSize: "14",
        padding: { top: 4, bottom: 8 }
    },
    {
        type: "Row",
        fillMaxWidth: true,
        verticalAlignment: "Center",
        children: [
            { type: "Text", text: score + "/10", color: "#FFFFFF", textSize: "50", bold: true },
            { type: "Spacer", isWeighted: true },
            {
                type: "Column",
                horizontalAlignment: "End",
                children: [
                    { type: "Text", text: windnu, color: "#FFFFFF", textSize: "24", align: "Right" },
                    { type: "Text", text: windvlagen, color: "#E0E0E0", textSize: "14", align: "Right" }
                ]
            }
        ]
    }
];

// Grafiek onderaan, alleen als data.grafiekUrl bij het ophalen daadwerkelijk gevuld was (Actie 1
// zet 'm dan op "") - anders geen Image-element, i.p.v. een kapot-plaatje-icoon in de widget.
if (grafiekurl) {
    kolomKinderen.push({
        type: "Image",
        url: grafiekurl,
        contentScale: "Fit",
        fillMaxWidth: true,
        padding: { top: 8 }
    });
}

var layout = {
    type: "Box",
    backgroundColor: kleur,
    fillMaxSize: true,
    padding: 16,
    children: [
        {
            type: "Column",
            fillMaxSize: true,
            children: kolomKinderen
        }
    ]
};

setLocal("widgetlayout", JSON.stringify(layout));
